export function Navbar({
  brand = "{{brand}}",
  activeLabel = "{{activeLabel}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
  sticky = {{sticky}},
}) {
  const dark = variant === "dark";
  return (
    <nav aria-label="Primary" style={{ display: "flex", alignItems: "center", gap: 32, padding: "14px 20px", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 14, background: dark ? "#241430" : "#FAF7F2", color: dark ? "#FAF7F2" : "#241430", boxShadow: sticky ? "0 6px 20px rgba(36,20,48,.16)" : "none" }}>
      <span style={{ fontWeight: 700, fontSize: 16 }}>{brand}</span>
      <div style={{ display: "flex", gap: 20 }}>
        <a href="#" aria-current="page" style={{ textDecoration: "none", color: "inherit", opacity: 1, paddingBottom: 4, borderBottom: "2px solid " + accent, fontWeight: 600 }}>{activeLabel}</a>
        <a href="#" style={{ textDecoration: "none", color: "inherit", opacity: .65, paddingBottom: 4, borderBottom: "2px solid transparent" }}>Projects</a>
        <a href="#" style={{ textDecoration: "none", color: "inherit", opacity: .65, paddingBottom: 4, borderBottom: "2px solid transparent" }}>Team</a>
      </div>
    </nav>
  );
}
